/**
 * Intel HEX Parser for CH552 Firmware
 * Converts standard .hex files generated by Arduino IDE / SDCC into raw binary buffers.
 */
class IntelHexParser {
  /**
   * Parses an Intel HEX string.
   * @param {string} hexText - Intel HEX file contents.
   * @param {number} maxFlashSize - Maximum flash size (default 11264 bytes = 0x2C00).
   * @returns {{ data: Uint8Array, startAddr: number, endAddr: number, crc16: number }}
   */
  static parse(hexText, maxFlashSize = 11264) {
    const memory = new Uint8Array(maxFlashSize).fill(0xFF);
    let minAddress = maxFlashSize;
    let maxAddress = 0;
    let extendedAddress = 0;

    const lines = hexText.split(/\r?\n/);

    for (let lineIndex = 0; lineIndex < lines.length; lineIndex++) {
      let line = lines[lineIndex].trim();
      if (!line || !line.startsWith(':')) continue;

      const byteCount = parseInt(line.substring(1, 3), 16);
      const address = parseInt(line.substring(3, 7), 16) + extendedAddress;
      const recordType = parseInt(line.substring(7, 9), 16);

      if (recordType === 0x01) {
        // End of File Record
        break;
      } else if (recordType === 0x02) {
        // Extended Segment Address Record
        extendedAddress = parseInt(line.substring(9, 13), 16) << 4;
      } else if (recordType === 0x04) {
        // Extended Linear Address Record
        extendedAddress = parseInt(line.substring(9, 13), 16) << 16;
      } else if (recordType === 0x00) {
        // Data Record
        for (let i = 0; i < byteCount; i++) {
          const targetAddr = address + i;
          if (targetAddr >= maxFlashSize) {
            throw new Error(`Firmware address 0x${targetAddr.toString(16)} exceeds user flash partition (max 0x${maxFlashSize.toString(16)})`);
          }
          const byteVal = parseInt(line.substring(9 + i * 2, 11 + i * 2), 16);
          memory[targetAddr] = byteVal;

          if (targetAddr < minAddress) minAddress = targetAddr;
          if (targetAddr > maxAddress) maxAddress = targetAddr;
        }
      }
    }

    if (maxAddress < minAddress) {
      minAddress = 0;
      maxAddress = 0;
    }

    // Align length to even number of bytes for 16-bit word writing
    let length = (maxAddress + 1);
    if (length % 2 !== 0) length++;

    // Calculate CRC-16-CCITT over [0 .. length]
    let crc = 0xFFFF;
    for (let i = 0; i < length; i++) {
      crc ^= (memory[i] << 8);
      for (let b = 0; b < 8; b++) {
        if (crc & 0x8000) {
          crc = ((crc << 1) ^ 0x1021) & 0xFFFF;
        } else {
          crc = (crc << 1) & 0xFFFF;
        }
      }
    }

    return {
      data: memory.subarray(0, length),
      startAddr: minAddress,
      endAddr: length,
      crc16: crc
    };
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = IntelHexParser;
}
